{"implementation":"def solve(case):
    threshold = case['payload']['threshold']
    calls = case['payload']['calls']
    result = []
    for call in calls:
        if call['parseable']:
            delta = call['loss_without_call'] - call['loss_with_call']
            per_token = delta / call['prediction_tokens']
            if per_token > threshold:
                result.append(call['call_id'])
    return result"}
